package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenRepresentationConversionsScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1";
 private static Question q(String id,String raw){return new Question(id,RepresentationConversions.prompt(id,raw),"-999.123456789","999");}
 @Test public void normalSixNaSevenTopicsUseAllFreshFiniteOriginalsAndOldestInBothMultipleChoiceModes(){
  var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow();
  for(String id:RepresentationConversions.IDS){assertTrue(pack.inGrade(id,7));assertFalse(pack.inGrade(id,6));assertEquals(1,Catalog.ALL.stream().filter(s->s.id.equals(id)).count());assertEquals("representationConversion",Catalog.get(id).family);CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,id,7);int count=RepresentationConversions.domainSize(id);assertTrue(count>100);
   for(boolean mc:List.of(false,true)){Generator generator=new Generator(new Random(362));List<String> recent=new ArrayList<>();boolean zero=false,aboveOne=false;
    for(int i=0;i<count;i++){Question q=generator.next(id,recent,mc,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=RepresentationConversions.read(q);assertNotNull(g);zero|=g.value().isZero();aboveOne|=g.value().compareTo(Rational.ONE)>0;assertTrue(limits.allows(q));assertTrue(g.value().compareTo(Rational.of(2))<=0);assertTrue(q.choices.isEmpty());assertTrue(q.choiceLabels.isEmpty());assertEquals(-1,q.correctChoice);assertFalse(q.stepSupport);assertEquals(1,q.answers.length);assertTrue(new Checker().check(q,List.of(),List.of(q.answers[0])).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());if(g.target().equals("fraction")){assertEquals("number",q.kind);assertEquals("fraction",q.answerFormat);assertTrue(FractionInput.available(q));assertTrue(FractionInput.defaultFraction(q));assertNotNull(RepresentationConversions.guide(q).resultNumeratorFrame);}else{assertEquals(g.target().equals("decimal")?"conversionDecimal":"conversionPercent",q.kind);assertFalse(FractionInput.available(q));assertFalse(FractionInput.defaultFraction(q));}
    }assertTrue(zero&&aboveOne);assertEquals(recent.get(0),generator.next(id,recent,mc,limits).signature());
   }
   Question created=new Generator(new Random(362)).create(Catalog.get(id));assertNotNull(RepresentationConversions.read(created));assertTrue(new Checker().check(created,List.of(),List.of(created.answers[0])).correct());
  }
 }
 @Test public void publicRoleAndResultFiltersNeverUsePrivateKeysOrSelectedFiniteDomainsAsValidity(){
  Question q=q(RepresentationConversions.FP,"1/5");q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;CurriculumLimits selected=GlobalCurriculum.limits(SYSTEM,q.skillId,7);assertTrue(selected.allows(q));q.expression=null;q.answers=null;assertTrue(selected.allows(q));assertTrue(new CurriculumLimits("maxGiven=5;minGiven=0;maxResult=20;denominators=5").allows(q));assertFalse(new CurriculumLimits("maxGiven=4").allows(q));assertFalse(new CurriculumLimits("minGiven=2").allows(q));assertFalse(new CurriculumLimits("maxResult=19").allows(q));assertFalse(new CurriculumLimits("denominators=10").allows(q));assertTrue(new CurriculumLimits("percentages=20").allows(q));assertFalse(new CurriculumLimits("percentages=25").allows(q));assertTrue(new CurriculumLimits("unitFractions=true").allows(q));assertSame(stored,q.studyGuide);assertNull(q.expression);assertNull(q.answers);
  Question general=q(RepresentationConversions.PD,"350.50%");assertNotNull(RepresentationConversions.read(general));assertFalse(GlobalCurriculum.limits(SYSTEM,general.skillId,7).allows(general));assertTrue(CurriculumLimits.NONE.allows(general));assertTrue(new Checker().check(general,List.of(),List.of("3.505")).correct());assertFalse(new CurriculumLimits("maxGiven=350").allows(general));assertTrue(new CurriculumLimits("maxGiven=351;maxResult=4;answerDecimalPlaces=3").allows(general));assertFalse(new CurriculumLimits("answerDecimalPlaces=2").allows(general));assertFalse(new CurriculumLimits("answerDomain=integer").allows(general));
  Question cycle=q(RepresentationConversions.FD,"1/7");cycle.expression=null;cycle.answers=null;assertTrue(CurriculumLimits.NONE.allows(cycle));assertTrue(new CurriculumLimits("decimalPlaces=1").allows(cycle));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(cycle));assertTrue(new Checker().check(cycle,List.of(),List.of("0.(142857)")).correct());Question decimal=q(RepresentationConversions.DF,"0.5000");assertFalse(new CurriculumLimits("decimalPlaces=3").allows(decimal));assertTrue(CurriculumLimits.NONE.allows(decimal));
 }
 @Test public void fractionPresentationFollowsPublicTargetEvenWhenPrivateFormatsArePoisoned(){
  Question fraction=q(RepresentationConversions.DF,"0.25");fraction.kind="number";fraction.answerFormat="decimal";assertTrue(FractionInput.available(fraction));assertTrue(FractionInput.defaultFraction(fraction));Learning.Session s=new Learning.Session();s.question=fraction;s.answers=new ArrayList<>(List.of(""));assertTrue(FractionInput.form(s,0).fraction);assertTrue(FractionInput.setPart(s,0,1,"1"));assertTrue(FractionInput.setPart(s,0,2,"4"));assertEquals("1/4",s.answers.get(0));assertTrue(new Checker().check(fraction,List.of(),s.answers).correct());
  Question decimal=q(RepresentationConversions.PD,"25%");decimal.answerFormat="fraction";assertFalse(FractionInput.available(decimal));assertFalse(FractionInput.defaultFraction(decimal));Question invalid=q(RepresentationConversions.DF,"bad");assertFalse(FractionInput.available(invalid));assertFalse(FractionInput.defaultFraction(invalid));
 }
 @Test public void oldExplicitPercentAndNamibiaExactRoundedSimplestContractsArePreserved(){
  Question hundredths=PercentageNotation.make(PercentageNotation.FRACTION,35);assertEquals("hundredthsFraction",hundredths.answerFormat);assertTrue(new Checker().check(hundredths,List.of(),List.of("35/100")).correct());assertFalse(new Checker().check(hundredths,List.of(),List.of("7/20")).correct());assertEquals(3,HelpPlan.forQuestion(hundredths).size());assertEquals("percentage-notation-v1",HelpPlan.forQuestion(hundredths).restore(null,hundredths.id).teachingVersion);
  Question reverse=DecimalPercentReverse.make(350);assertTrue(new Checker().check(reverse,List.of(),List.of("35")).correct());assertFalse(new Checker().check(reverse,List.of(),List.of("35%")).correct());assertEquals(4,HelpPlan.forQuestion(reverse).size());Question mixed=FractionPercentEquivalence.make(1,2);assertEquals(2,mixed.answers.length);assertTrue(new Checker().check(mixed,List.of(),List.of("0.5","50")).correct());Question amount=PercentAmountRelations.amount(200,35);assertTrue(new Checker().check(amount,List.of(),List.of("70")).correct());
  Question rounded=new Question(FractionToDecimalCheck.ID,FractionDecimalDivision.prompt("1","3"),"poison","999");assertTrue(new Checker().check(rounded,List.of(),List.of("0.333")).correct());assertEquals(23,HelpPlan.forQuestion(rounded).size());Question recall=new Question(FractionDecimalRecall.ID,FractionDecimalRecall.prompt("1","3"),"poison","999");assertTrue(new Checker().check(recall,List.of(),List.of("0.(3)")).correct());assertFalse(new Checker().check(recall,List.of(),List.of("0.333")).correct());assertEquals(4,HelpPlan.forQuestion(recall).size());Question reduced=DecimalToFractionSupply.makeReduced(0,45,2);assertTrue(new Checker().check(reduced,List.of(),List.of("9/20")).correct());assertEquals(7,HelpPlan.forQuestion(reduced).size());Question meaning=PercentageMeaning.make(35);assertTrue(new Checker().check(meaning,List.of(),List.of("100","35%")).correct());assertEquals(4,HelpPlan.forQuestion(meaning).size());assertEquals(2,GlobalCurriculum.limits(SYSTEM,DecimalToFractionSupply.ID,6).decimalPlaces(1));
 }
}
